      "sourceDocument": "KONKI_MISSION_BIBLE_V1.md",
      "sourceDocumentVersion": "1",
      "sourceSection": "# M08 — Consiga uma condição melhor",
      "sourceStartLine": 1040,
      "sourceEndLine": 1206,
      "sourceDocumentHash": "f361e11a911ba0ed8e96248819a798c96e999b9db18b533641421a2f8ddf23b4",
      "contentHash": "7ee28d10bc263e48ca8f347e8c2a2ad9a7c11f34c72bd5574304f484e89691fc"
