      "sourceDocument": "KONKI_MISSION_BIBLE_V1.md",
      "sourceDocumentVersion": "1",
      "sourceSection": "# M18 — Crie com um limite difícil",
      "sourceStartLine": 2359,
      "sourceEndLine": 2484,
      "sourceDocumentHash": "f361e11a911ba0ed8e96248819a798c96e999b9db18b533641421a2f8ddf23b4",
      "contentHash": "ff99102c2089fff4b6a59f8e54204db88fc5378c74bac149bc8908adc9be3f8a"
